#ifndef ALGOL_TABLES_H
#define ALGOL_TABLES_H

#include <cstddef>
#include <span>
#include <stdexcept>
#include <string_view>
#include <vector>

#include "stdarray.h"

//
// Tables of the original compiler, at their original addresses.
// Data in tables_data.cpp, generated by scripts/gen-tables.py; see doc/tables.md.
//
namespace tables {

struct Table {
    unsigned addr{};             // original address of the first word
    std::span<const Word> words; // contents

    unsigned end() const { return addr + words.size(); }

    // Word at an original address.
    Word at(unsigned address) const
    {
        if (address < addr || address >= end())
            throw std::out_of_range("table address out of range");
        return words[address - addr];
    }
};

struct InitWord {
    unsigned addr{};
    Word value{};
};

// The whole overlay ALGOL, from image_base.
extern const unsigned image_base;
extern const Word image[];
extern const size_t image_size;

extern const InitWord workspace_init[];
extern const size_t workspace_init_size;

// UTF-8 text in ISO (KOI-7) words, 6 characters per word, the last padded
// with zero bytes. A byte 0200-0277 alone (not UTF-8) is copied as is: an
// argument escape of the formats (G27733).
std::vector<Word> iso_words(std::string_view text);
Word iso_word(std::string_view text); // at most 6 characters

extern const Table symattr, warnings, commsg, chclass, syntext, errclass, p2msg, p2disp, p3class, p3mask,
    p3rewr, p3jump, p3regs, template_, p4disp, linetab, isotext, rtnames, summary;

} // namespace tables

#endif
